// Ashur 0.70.0: writes the Basis worker KTX2Loader would build in a blob, as a real file the core serves with its own CSP.
import { readFileSync, writeFileSync } from "node:fs";
import { KTX2Loader } from "three/examples/jsm/loaders/KTX2Loader.js";
const fn = KTX2Loader.BasisWorker.toString();
const body = [
  "/* Ashur 0.70.0: the worker three's KTX2Loader 0.187.0 builds in a blob, as a file (generated by deploy/build_three.sh) */",
  "/* constants */",
  "let _EngineFormat = " + JSON.stringify(KTX2Loader.EngineFormat),
  "let _EngineType = " + JSON.stringify(KTX2Loader.EngineType),
  "let _TranscoderFormat = " + JSON.stringify(KTX2Loader.TranscoderFormat),
  "let _BasisFormat = " + JSON.stringify(KTX2Loader.BasisFormat),
  "/* basis_transcoder.js */",
  readFileSync("node_modules/three/examples/jsm/libs/basis/basis_transcoder.js", "utf8"),
  "/* worker */",
  fn.substring(fn.indexOf("{") + 1, fn.lastIndexOf("}")),
].join("\n");
writeFileSync(process.argv[2], body);
